import Vue from 'vue';
import { Component, Emit, Prop } from 'vue-property-decorator';
import { SvgIcon } from '@game-studio/svg-icons';

@Component({
    name: 'GameWindow',
    components: {
        SvgIcon
    }
})
export default class GameWindow extends Vue {
    @Prop({
        required: true,
        type: String
    })
    public displayMode: string;

    @Prop({
        required: true,
        type: String
    })
    public orientation: string;

    @Prop({
        required: false,
        type: Boolean,
        default: true
    })
    public showControls: boolean;

    @Prop({
        required: true,
        type: Boolean,
        default: false
    })
    public visible: boolean;

    @Prop({
        required: true,
        type: String
    })
    public gameName: string;
    
    @Prop({
        required: false,
        type: Boolean,
        default: true
    })
    public hideControls: boolean;

    @Prop({
        required: false,
        type: Boolean,
        default: true
    })
    public canPopout: boolean;

    @Prop({
        required: false,
        type: String,
        default: ''
    })
    public errorMessage: string;

    @Emit('onClose')
    public onClose() {
    }

    @Emit('onPopout')
    public onPopout() {
    }
}
